tr=pd.read_csv('b3_te_zt900_train.csv'); p=pd.read_csv('b3_te_zt900_pool.csv'); cols=tr.columns[:-1]
# inspect key candidates: all train with Jaccard support similarly
for cid in ['c001','c006','c041','c008','c021','c012','c052','c054','c063','c025','c097','c057','c086','c078','c035','c034','c023']:
 q=p.set_index('candidate_id').loc[cid]; supp=set(q.index[q>1e-12]);
